import java.io.BufferedInputStream;
import java.io.IOException;

public class Main {
    static class FastScanner {
        private final BufferedInputStream in = new BufferedInputStream(System.in);
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int s = fs.nextInt();
        int t = fs.nextInt();
        boolean[][] connected = new boolean[s + 1][s + 1];

        for (int i = 0; i < t; i++) {
            int x = fs.nextInt();
            int y = fs.nextInt();
            connected[x][y] = true;
            connected[y][x] = true;
        }

        int p = fs.nextInt();
        int possible = 0;

        for (int i = 0; i < p; i++) {
            int n = fs.nextInt();
            int previous = fs.nextInt();
            boolean valid = true;

            for (int j = 1; j < n; j++) {
                int current = fs.nextInt();
                if (!connected[previous][current]) {
                    valid = false;
                }
                previous = current;
            }

            if (valid) possible++;
        }

        System.out.println(possible);
    }
}
